import React from 'react';
import Slider from 'react-slick';
import '../styles/ClientesCarrusel.css';

const logos = [
  { src: '/clientes/logo1.png', alt: 'Cliente 1' },
  { src: '/clientes/logo2.png', alt: 'Cliente 2' },
  { src: '/clientes/logo3.png', alt: 'Cliente 3' },
  { src: '/clientes/logo4.png', alt: 'Cliente 4' },
  { src: '/clientes/logo5.png', alt: 'Cliente 5' },
  { src: '/clientes/logo6.png', alt: 'Cliente 6' },
  { src: '/clientes/logo7.png', alt: 'Cliente 7' },
  { src: '/clientes/logo8.png', alt: 'Cliente 8' },
];

const ClientesCarrusel = () => {
  const settings = {
    dots: false,
    infinite: true,
    slidesToShow: 6,
    slidesToScroll: 1,
    autoplay: true,
    speed: 8000, // Duración de la animación (más alto = más lento)
    autoplaySpeed: 0, // Sin pausa entre transiciones
    cssEase: "linear", // Movimiento a velocidad constante
    pauseOnHover: true, // Se detiene al pasar el ratón
    arrows: false, // Oculta las flechas de navegación
    responsive: [
      {
        breakpoint: 1024,
        settings: {
          slidesToShow: 4,
        }
      },
      {
        breakpoint: 600,
        settings: {
          slidesToShow: 3,
        }
      },
      {
        breakpoint: 480,
        settings: {
          slidesToShow: 2,
        }
      }
    ]
  };

  return (
    <div className="clientes-carrusel">
      <Slider {...settings}>
        {logos.map((logo, index) => (
          <div key={index} className="cliente-logo">
            <img src={logo.src} alt={logo.alt} />
          </div>
        ))}
      </Slider>
    </div>
  );
};

export default ClientesCarrusel;
